import json, pathlib

def T(ru, tg): return {"ru": ru, "tg": tg}
def ex(ru, tg): return {"ru": ru, "tg": tg}
def err(wrong, right, ru, tg): return {"wrong": wrong, "right": right, "why": T(ru, tg)}
def q(text_ru, text_tg, opts, a, e_ru, e_tg): return {"q": T(text_ru, text_tg), "opts": opts, "a": a, "expl": T(e_ru, e_tg)}

